'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import {
    CheckCircle2,
    Printer,
    Mail,
    MessageSquare,
    PlusCircle,
    LayoutDashboard,
    Clock,
    Package,
    Utensils,
    ShoppingBag,
    Truck
} from 'lucide-react';
import { usePOS } from '@/modules/pos/context/POSContext';
import '../styles/pos-rush.css';

export const POSConfirmationScreen: React.FC = () => {
    const router = useRouter();
    const { orderResult, clearCart, setCustomer, setTable } = usePOS();

    // Local UI State
    const [isPrinting, setIsPrinting] = useState(false);
    const [sentStatus, setSentStatus] = useState<{ sms: boolean; email: boolean }>({ sms: false, email: false });
    const [kitchenStatus, setKitchenStatus] = useState<'ROUTING' | 'SENT' | 'PREPARING'>('ROUTING');

    // Simulate Kitchen Routing Lifecycle
    useEffect(() => {
        const routeTimer = setTimeout(() => setKitchenStatus('SENT'), 1500);
        const prepTimer = setTimeout(() => setKitchenStatus('PREPARING'), 4000);
        return () => {
            clearTimeout(routeTimer);
            clearTimeout(prepTimer);
        };
    }, []);

    const handlePrint = () => {
        setIsPrinting(true);
        setTimeout(() => setIsPrinting(false), 2000);
    };

    const handleNewOrder = () => {
        clearCart();
        setCustomer(null);
        setTable(null);
        router.push('/pos/menu');
    };

    if (!orderResult) {
        return (
            <div className="pos-screen" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--pos-bg-surface)' }}>
                <div style={{ textAlign: 'center' }}>
                    <div style={{ width: '64px', height: '64px', border: '4px solid rgba(255,255,255,0.1)', borderTopColor: 'var(--pos-action-primary)', borderRadius: '50%', animation: 'spin 1s linear infinite', margin: '0 auto 24px' }} />
                    <h2 style={{ color: 'white', fontWeight: 900 }}>Finalizing Order...</h2>
                </div>
            </div>
        );
    }

    return (
        <div className="pos-screen" style={{ background: 'var(--pos-bg-surface)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '32px', overflow: 'hidden' }}>
            {/* Celebration Background */}
            <div style={{ position: 'fixed', top: '-10%', left: '-10%', width: '120%', height: '120%', background: 'radial-gradient(circle at center, rgba(16, 185, 129, 0.08) 0%, transparent 70%)', zIndex: 0, pointerEvents: 'none' }} />

            <div style={{ width: '100%', maxWidth: '840px', zIndex: 1, animation: 'posFadeInUp 0.6s cubic-bezier(0.16, 1, 0.3, 1)' }}>
                {/* Success Header */}
                <div style={{ textAlign: 'center', marginBottom: '48px' }}>
                    <div style={{ width: '120px', height: '120px', background: '#10B981', borderRadius: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', margin: '0 auto 24px', boxShadow: '0 20px 40px rgba(16, 185, 129, 0.3)' }}>
                        <CheckCircle2 size={72} strokeWidth={2.5} />
                    </div>
                    <h1 style={{ fontSize: '56px', fontWeight: 900, color: 'white', marginBottom: '8px', letterSpacing: '-0.03em' }}>Order Confirmed</h1>
                    <p style={{ fontSize: '20px', color: 'rgba(255,255,255,0.6)', fontWeight: 600 }}>Kitchen has accepted the ticket successfully</p>
                </div>

                {/* Info Dashboard */}
                <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 1fr 1fr', gap: '20px', marginBottom: '40px' }}>
                    {/* Order ID Card */}
                    <div style={{ background: 'var(--pos-bg-card)', border: '1px solid var(--pos-border-subtle)', borderRadius: '28px', padding: '24px', textAlign: 'center' }}>
                        <span style={{ fontSize: '12px', fontWeight: 900, color: 'var(--pos-text-muted)', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Order Number</span>
                        <div style={{ fontSize: '32px', fontWeight: 900, color: 'white', marginTop: '4px' }}>{orderResult.orderId}</div>
                    </div>

                    {/* Fulfillment Card */}
                    <div style={{ background: 'var(--pos-bg-card)', border: '1px solid var(--pos-border-subtle)', borderRadius: '28px', padding: '24px', textAlign: 'center' }}>
                        <span style={{ fontSize: '12px', fontWeight: 900, color: 'var(--pos-text-muted)', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Fulfillment</span>
                        <div style={{ fontSize: '20px', fontWeight: 900, color: '#F59E0B', marginTop: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}>
                            {orderResult.fulfillment === 'Dine-In' && <Utensils size={20} />}
                            {orderResult.fulfillment === 'Pickup' && <ShoppingBag size={20} />}
                            {orderResult.fulfillment === 'Delivery' && <Truck size={20} />}
                            {orderResult.fulfillment.toUpperCase()}
                        </div>
                    </div>

                    {/* Customer Card */}
                    <div style={{ background: 'var(--pos-bg-card)', border: '1px solid var(--pos-border-subtle)', borderRadius: '28px', padding: '24px', textAlign: 'center' }}>
                        <span style={{ fontSize: '12px', fontWeight: 900, color: 'var(--pos-text-muted)', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Customer</span>
                        <div style={{ fontSize: '20px', fontWeight: 900, color: '#3B82F6', marginTop: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {orderResult.customerName || 'Walk-In'}
                        </div>
                    </div>
                </div>

                {/* Secondary Stats */}
                <div style={{ display: 'flex', justifyContent: 'center', gap: '48px', marginBottom: '48px', padding: '16px', background: 'rgba(255,255,255,0.03)', borderRadius: '24px', border: '1px solid rgba(255,255,255,0.05)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <Clock size={20} color="rgba(255,255,255,0.4)" />
                        <span style={{ color: 'rgba(255,255,255,0.6)', fontWeight: 700 }}>ETA: <strong style={{ color: 'white' }}>{orderResult.eta}</strong></span>
                    </div>
                    <div style={{ width: '1px', height: '20px', background: 'rgba(255,255,255,0.1)' }} />
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <Package size={20} color="rgba(255,255,255,0.4)" />
                        <span style={{ color: 'rgba(255,255,255,0.6)', fontWeight: 700 }}>Items Charged: <strong style={{ color: 'white' }}>{orderResult.items}</strong></span>
                    </div>
                </div>

                {/* Action Buttons */}
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '16px', marginBottom: '40px' }}>
                    <button onClick={handlePrint} className="pos-btn-secondary" style={{ height: '80px', borderRadius: '24px', fontWeight: 900, fontSize: '15px', gap: '12px' }}>
                        {isPrinting ? 'PRINTING...' : <><Printer size={24} /> PRINT RECEIPT</>}
                    </button>
                    <button onClick={() => setSentStatus({ ...sentStatus, sms: true })} className="pos-btn-secondary" style={{ height: '80px', borderRadius: '24px', fontWeight: 900, fontSize: '15px', gap: '12px', color: sentStatus.sms ? '#10B981' : 'white', borderColor: sentStatus.sms ? '#10B981' : 'rgba(255,255,255,0.1)' }}>
                        {sentStatus.sms ? <CheckCircle2 size={24} /> : <MessageSquare size={24} />} {sentStatus.sms ? 'SMS SENT' : 'SEND SMS'}
                    </button>
                    <button onClick={() => setSentStatus({ ...sentStatus, email: true })} className="pos-btn-secondary" style={{ height: '80px', borderRadius: '24px', fontWeight: 900, fontSize: '15px', gap: '12px', color: sentStatus.email ? '#10B981' : 'white', borderColor: sentStatus.email ? '#10B981' : 'rgba(255,255,255,0.1)' }}>
                        {sentStatus.email ? <CheckCircle2 size={24} /> : <Mail size={24} />} {sentStatus.email ? 'EMAIL SENT' : 'SEND EMAIL'}
                    </button>
                </div>

                <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                    <button onClick={handleNewOrder} className="pos-btn-primary" style={{ height: '96px', borderRadius: '28px', fontSize: '24px', fontWeight: 900, boxShadow: '0 20px 40px rgba(0,0,0,0.4)' }}>
                        <PlusCircle size={28} /> START NEW ORDER
                    </button>
                    <button onClick={() => router.push('/pos/dashboard')} className="pos-btn-secondary" style={{ height: '72px', borderRadius: '24px', fontWeight: 900 }}>
                        <LayoutDashboard size={20} /> BACK TO DASHBOARD
                    </button>
                </div>
            </div>

            {/* Kitchen routing status (Section 10.1 Rules) */}
            <div style={{ position: 'absolute', bottom: '40px', left: '50%', transform: 'translateX(-50%)', display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 24px', background: 'rgba(255,255,255,0.05)', borderRadius: '9999px', backdropFilter: 'blur(10px)', border: '1px solid rgba(255,255,255,0.1)' }}>
                <div style={{ width: '10px', height: '10px', borderRadius: '50%', background: kitchenStatus === 'ROUTING' ? '#3B82F6' : (kitchenStatus === 'SENT' ? '#10B981' : '#F59E0B'), boxShadow: `0 0 10px ${kitchenStatus === 'ROUTING' ? '#3B82F6' : '#10B981'}`, animation: kitchenStatus !== 'SENT' ? 'posPulse 2s infinite' : 'none' }} />
                <span style={{ fontSize: '11px', fontWeight: 900, color: 'white', textTransform: 'uppercase', letterSpacing: '0.15em' }}>
                    {kitchenStatus === 'ROUTING' && 'Routing request to Kitchen KDS...'}
                    {kitchenStatus === 'SENT' && 'Order Routed & Accepted by Kitchen'}
                    {kitchenStatus === 'PREPARING' && 'Kitchen: Now Preparing Your Order'}
                </span>
            </div>

            <style>{`
                @keyframes posPulse { 0% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(1.2); } 100% { opacity: 1; transform: scale(1); } }
                @keyframes posFadeInUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
                @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
            `}</style>
        </div>
    );
};

export default POSConfirmationScreen;
